<description>
Makes the suffix/TLD check case-insensitive when parsing `.onion` addresses, as is already done for I2P hostnames. With the current code, a name like `<addr>.ONION` will not be parsed as a Tor address, and will instead fall through to regular hostname resolution.
</description>

<commits>
0574f096ab netaddress: make .onion suffix check case-insensitive
</commits>

<files>
src/netaddress.cpp  +3/-2
src/test/net_tests.cpp  +7/-0

(test/bench/ci lines: 7)
</files>

<patch>
diff --git a/src/netaddress.cpp b/src/netaddress.cpp
index acad7f71a6..419252c97e 100644
--- a/src/netaddress.cpp
+++ b/src/netaddress.cpp
@@ -228,8 +228,9 @@ bool CNetAddr::SetSpecial(std::string_view addr)

 bool CNetAddr::SetTor(std::string_view addr)
 {
-    if (!addr.ends_with(".onion")) return false;
-    addr.remove_suffix(6);
+    static constexpr std::string_view suffix{".onion"};
+    if (addr.size() < suffix.size() || ToLower(addr.substr(addr.size() - suffix.size())) != suffix) return false;
+    addr.remove_suffix(suffix.size());
     auto input = DecodeBase32(addr);

     if (!input) {
diff --git a/src/test/net_tests.cpp b/src/test/net_tests.cpp
index 4b68b3fdd0..da92db0756 100644
--- a/src/test/net_tests.cpp
+++ b/src/test/net_tests.cpp
@@ -216,6 +216,13 @@ BOOST_AUTO_TEST_CASE(cnetaddr_basic)
     BOOST_CHECK(!addr.IsAddrV1Compatible());
     BOOST_CHECK_EQUAL(addr.ToStringAddr(), torv3_addr);

+    // TORv3, mixed case
+    const char* torv3_addr_mixed_case = "PG6Mmjiyjmcrsslvykfwnntlaru7p5svn6y2ymmju6nubxndf4pscryd.ONION";
+    BOOST_REQUIRE(addr.SetSpecial(torv3_addr_mixed_case));
+    BOOST_REQUIRE(addr.IsValid());
+    BOOST_REQUIRE(addr.IsTor());
+    BOOST_CHECK_EQUAL(addr.ToStringAddr(), ToLower(torv3_addr_mixed_case));
+
     // TORv3, broken, with wrong checksum
     BOOST_CHECK(!addr.SetSpecial("pg6mmjiyjmcrsslvykfwnntlaru7p5svn6y2ymmju6nubxndf4pscsad.onion"));


</patch>
